    @Test("fermata")
    func fermata() async throws {
        let reader: Gp7To8Importer = await Gp7ImporterTest.prepareImporterWithFile("guitarpro7/fermata.gp")
        let score: Score = try reader.readScore()
        try TestGlobals.expect(jsNonNull(score.masterBars.jsElement(0).fermata).size).toBe(5.0)
        try TestGlobals.expect(jsNonNull(score.masterBars.jsElement(1).fermata).size).toBe(5.0)
        try TestGlobals.expect(jsNonNull(score.masterBars.jsElement(2).fermata).size).toBe(5.0)
        let offsets: List<Double> = List<Double>(0.0, jsOr(MidiUtils.QuarterTime * (1.0 / 2.0), 0), jsOr(MidiUtils.QuarterTime * (1.0 / 1.0), 0), jsOr(MidiUtils.QuarterTime * (2.0 / 1.0), 0), jsOr(MidiUtils.QuarterTime * (3.0 / 1.0), 0))
        let types: List<FermataType> = List<FermataType>(FermataType.Short, FermataType.Medium, FermataType.Long)
        do {
            var i: Double = 0.0
            while i < 3 {
                let masterBar: MasterBar = score.masterBars[(i).toInt()]
                try TestGlobals.expect(jsNonNull(masterBar.fermata).size).toBe(5.0)
                for offset in offsets {
                    let fermata: Fermata? = try jsNonNull(masterBar.fermata).get(offset)
                    TestGlobals.expect(fermata).toBeTruthy()
                    try TestGlobals.expect(jsNonNull(fermata).type).toBe(types[(i).toInt()])
                }
                let beats: List<Beat> = try score.tracks.jsElement(0).staves.jsElement(0).bars.jsElement((i).toInt()).voices.jsElement(0).beats
                for beat in beats {
                    let fermata: Fermata? = try jsNonNull(masterBar.fermata).get(beat.playbackStart)
                    let beatFermata: Fermata? = beat.fermata
                    TestGlobals.expect(beatFermata).toBeTruthy()
                    TestGlobals.expect(fermata).toBeTruthy()
                    try TestGlobals.expect(jsNonNull(beatFermata).type).toBe(types[(i).toInt()])
                    try TestGlobals.expect(jsNonNull(fermata).type).toBe(types[(i).toInt()])
                }
                i += 1
            }
        }
    }

