        try TestGlobals.expect(jsNonNull(PercussionMapper.getArticulation(beats.jsElement(2).notes[0])).id).toBe(36.0)
        try TestGlobals.expect(beats.jsElement(3).notes.jsElement(0).string).toBe(2.0)
        try TestGlobals.expect(jsNonNull(PercussionMapper.getArticulation(beats.jsElement(3).notes[0])).id).toBe(36.0)
    }

